@import '../../utils/text-decoration.css';

:host {
  display: block;
}
.agent-sources {
  border-block-start: var(--dimension-stroke-width-012) solid var(--color-border-tertiary);
}
summary {
  align-items: center;
  cursor: default;
  display: flex;
  gap: var(--dimension-space-050);
  list-style: none;
  padding-block: var(--dimension-space-075);
}
summary::-webkit-details-marker {
  display: none;
}
details[open] summary ds-icon {
  transform: rotate(90deg);
}
ol {
  display: grid;
  gap: var(--dimension-space-075);
  margin: 0;
  padding: 0 0 var(--dimension-space-075) var(--dimension-space-150);
}
li {
  display: grid;
  gap: var(--dimension-space-025);
}
a {
  --ds-text-decoration-color: var(--color-foreground-tertiary);
  align-items: center;
  color: inherit;
  display: inline-flex;
  gap: var(--dimension-space-025);
  width: fit-content;
}

@media (prefers-reduced-motion: no-preference) {
  summary ds-icon {
    transition: transform var(--effect-motion-short-2);
  }
}

import { Component, Event, EventEmitter, Prop, h, Host } from '@stencil/core';
import { resolveSafeUrl } from '../../utils';
import type { AgentSource } from '../conversation-types';

@Component({ tag: 'ds-agent-source-list', styleUrl: 'AgentSourceList.css', scoped: true })
export class AgentSourceList {
  @Prop() items: AgentSource[] = [];
  @Prop() heading: string = 'Sources';
  @Prop() open: boolean = false;

  @Event() dsOpenChange!: EventEmitter<{ open: boolean }>;

  private hostname(href: string): string {
    try {
      return new URL(href).hostname;
    } catch {
      return '';
    }
  }

  render() {
    if (!this.items.length) return null;
    return (
      <Host>
        <details
          class="agent-sources"
          open={this.open}
          onToggle={(event: Event) =>
            this.dsOpenChange.emit({
              open: (event.currentTarget as HTMLDetailsElement).open,
            })
          }
        >
          <summary>
            <ds-icon name="ChevronRight" size="xs" color="inherit" />
            <ds-text variant="text-body-small" emphasis>
              {this.heading} · {this.items.length}
            </ds-text>
          </summary>
          <ol>
            {this.items.map(source => {
              const href = resolveSafeUrl(source.url);
              const hostname = href ? this.hostname(href) : '';
              return (
                <li>
                  {href ? (
                    <a
                      class="ds-text-decoration"
                      href={href}
                      target="_blank"
                      rel="noopener noreferrer"
                      aria-label={`${source.title} (${hostname}, opens in a new tab)`}
                    >
                      <ds-text variant="text-body-small" emphasis>
                        {source.title}
                      </ds-text>
                      <ds-icon name="ExternalLink" size="xs" color="inherit" />
                    </a>
                  ) : (
                    <ds-text variant="text-body-small" emphasis>
                      {source.title}
                    </ds-text>
                  )}
                  {hostname ? (
                    <ds-text variant="text-caption" color="secondary">
                      {hostname}
                    </ds-text>
                  ) : null}
                  {source.description ? (
                    <ds-text variant="text-body-small" color="secondary">
                      {source.description}
                    </ds-text>
                  ) : null}
                </li>
              );
            })}
          </ol>
        </details>
      </Host>
    );
  }
}
